function o(n,r=0,t=2){return Math.abs(n).toLocaleString("en-IN",{minimumFractionDigits:r,maximumFractionDigits:t})}function e(n,r=2){return`${n<0?"-":""}\u20B9${o(n,0,r)}`}function a(n,r=2){let t=n<0?"-":"",i=Math.abs(n)/1e5;return`${t}\u20B9${i.toFixed(r)} L`}function s(n){return Math.abs(n)>=1e5}function u(n,r={}){let{abbreviated:t=!1,maximumFractionDigits:i=2}=r;return t&&s(n)?a(n):e(n,i)}export{e as a,a as b,s as c,u as d};
